#!/usr/bin/env bash
# Generate /opt/km/supabase-official/.env with unique secrets.
# Reads JWT_SECRET/ANON_KEY/SERVICE_ROLE_KEY from /opt/km/secrets.env
set -euo pipefail

cd /opt/km/supabase-official
. /opt/km/secrets.env

# Placeholder domain - update these after the real domain is registered.
PUBLIC_URL="${SUPABASE_PUBLIC_URL:-https://supabase.km.example.com}"
APP_SITE_URL="${SITE_URL:-https://app.km.example.com}"

cat > .env <<EOF
# Generated by setup-env.sh - DO NOT COMMIT / DO NOT EXPOSE
POSTGRES_PASSWORD=$(openssl rand -hex 24)
JWT_SECRET=${JWT_SECRET}
ANON_KEY=${ANON_KEY}
SERVICE_ROLE_KEY=${SERVICE_ROLE_KEY}
SUPABASE_PUBLISHABLE_KEY=
SUPABASE_SECRET_KEY=
JWT_KEYS=
JWT_JWKS=
DASHBOARD_USERNAME=admin
DASHBOARD_PASSWORD=$(openssl rand -base64 18)
SECRET_KEY_BASE=$(openssl rand -base64 48)
REALTIME_DB_ENC_KEY=$(openssl rand -hex 8)
VAULT_ENC_KEY=$(openssl rand -hex 16)
PG_META_CRYPTO_KEY=$(openssl rand -base64 24)
LOGFLARE_PUBLIC_ACCESS_TOKEN=$(openssl rand -base64 24)
LOGFLARE_PRIVATE_ACCESS_TOKEN=$(openssl rand -base64 24)
S3_PROTOCOL_ACCESS_KEY_ID=$(openssl rand -hex 16)
S3_PROTOCOL_ACCESS_KEY_SECRET=$(openssl rand -hex 32)
SUPABASE_PUBLIC_URL=${PUBLIC_URL}
API_EXTERNAL_URL=${PUBLIC_URL}/auth/v1
POSTGRES_HOST=db
POSTGRES_DB=postgres
POSTGRES_PORT=5432
POOLER_PROXY_PORT_TRANSACTION=6543
POOLER_DEFAULT_POOL_SIZE=20
POOLER_MAX_CLIENT_CONN=100
POOLER_TENANT_ID=km
POOLER_DB_POOL_SIZE=5
STUDIO_DEFAULT_ORGANIZATION=KnowledgeMap
STUDIO_DEFAULT_PROJECT=km
OPENAI_API_KEY=
SITE_URL=${APP_SITE_URL}
ADDITIONAL_REDIRECT_URLS=
JWT_EXPIRY=86400
DISABLE_SIGNUP=true
MAILER_URLPATHS_CONFIRMATION=/auth/v1/verify
MAILER_URLPATHS_INVITE=/auth/v1/verify
MAILER_URLPATHS_RECOVERY=/auth/v1/verify
MAILER_URLPATHS_EMAIL_CHANGE=/auth/v1/verify
ENABLE_EMAIL_SIGNUP=false
ENABLE_EMAIL_AUTOCONFIRM=true
SMTP_ADMIN_EMAIL=admin@example.com
SMTP_HOST=supabase-mail
SMTP_PORT=2500
SMTP_USER=fake_mail_user
SMTP_PASS=fake_mail_password
SMTP_SENDER_NAME=fake_sender
ENABLE_ANONYMOUS_USERS=false
ENABLE_PHONE_SIGNUP=false
ENABLE_PHONE_AUTOCONFIRM=true
GLOBAL_S3_BUCKET=stub
REGION=stub
MINIO_ROOT_USER=supa-storage
MINIO_ROOT_PASSWORD=secret1234
STORAGE_TENANT_ID=km
FUNCTIONS_VERIFY_JWT=false
PGRST_DB_SCHEMAS=public,graphql_public
PGRST_DB_MAX_ROWS=1000
PGRST_DB_EXTRA_SEARCH_PATH=public
DOCKER_SOCKET_LOCATION=/var/run/docker.sock
GOOGLE_PROJECT_ID=GOOGLE_PROJECT_ID
GOOGLE_PROJECT_NUMBER=GOOGLE_PROJECT_NUMBER
API_GW_HTTP_PORT=8000
KONG_HTTP_PORT=8000
KONG_HTTPS_PORT=8443
ANON_KEY_ASYMMETRIC=
SERVICE_ROLE_KEY_ASYMMETRIC=
IMGPROXY_AUTO_WEBP=true
PROXY_DOMAIN=km.example.com
CERTBOT_EMAIL=admin@example.com
EOF

chmod 600 .env
echo "--- .env written ---"
grep -c '=' .env
